test('drone notifications collapse, dismiss individually and persist on refresh without deleting reports',async()=>{
 const {w}=await browser();try{const d=w.document,notice={id:randomUUID(),kind:'Pre-flight',name:'Example',period:'1',time:new Date().toISOString()},payload={eligible:true,notices:[notice],calendarEvents:[],calendarStatus:'ready',flyDay:false};const send=()=>d.dispatchEvent(new w.CustomEvent('nest-safety-notices',{detail:payload}));send();assert.equal(d.getElementById('safety-notifications').hidden,false);assert.equal(d.getElementById('safety-notifications').open,false);assert.equal(d.getElementById('safety-flight-settings-extra').open,false);d.querySelector('[data-dismiss-notice]').click();assert.equal(d.querySelector('[data-safety-report]'),null);send();assert.equal(d.querySelector('[data-safety-report]'),null);payload.notices.push({...notice,id:randomUUID()});send();assert.ok(d.querySelector('[data-safety-report]'));d.getElementById('safety-notice-dismiss-all').click();assert.equal(d.querySelector('[data-safety-report]'),null);assert.equal(payload.notices.length,2);w.NestAuth.identity.signedIn=false;d.dispatchEvent(new w.Event('nest-auth-change'));assert.equal(d.getElementById('safety-notifications').hidden,true);
 }finally{w.close();}
});
